--Q1. What is the total revenue generated by male vs. female customers?
select gender,sum(purchase_amount_usd) 
from customer_behaviour
GROUP BY gender;

--Q2. Which customers used a discount but still spent more than the average purchase amount? 
WITH cte_avg_purch AS(
select 
customer_id,
discount_applied,
purchase_amount_usd,
round(avg(purchase_amount_usd) over (),2) avg_purch_amt
from customer_behaviour)
SELECT * from cte_avg_purch
WHERE purchase_amount_usd>avg_purch_amt
ORDER BY customer_id

-- Q3. Which are the top 5 products with the highest average review rating?
select 
item_purchased,
avg_rating,
ROW_NUMBER() OVER (ORDER BY avg_rating DESC)
from
(select item_purchased, avg(new_review_rating) avg_rating
from customer_behaviour
GROUP BY item_purchased)t  ORDER BY avg_rating ;




--Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 

SELECT
	round(avg(purchase_amount_usd) FILTER ( WHERE shipping_type ='Express'),2) exp_avg_purc_amt,
	round(avg(purchase_amount_usd) FILTER ( WHERE shipping_type ='Standard'),2) std_avg_purc_amt,
	CASE 
	 WHEN round(avg(purchase_amount_usd) FILTER ( WHERE shipping_type ='Express'),2)>round(avg(purchase_amount_usd) FILTER ( WHERE shipping_type ='Standard'),2) THEN 'Express Shipping Sales More'
	 ELSE 'Standard Shipping Sales More'
	END
FROM 
customer_behaviour;

--Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.
SELECT
subscription_status,
round(avg(purchase_amount_usd),2),
sum(purchase_amount_usd)
FROM
customer_behaviour
GROUP BY subscription_status;

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select DISTINCT(discount_applied) from customer_behaviour;
-- By purchase amount
WITH CTE_product AS
(SELECT
item_purchased,
sum(purchase_amount_usd) prod_pur_amt
FROM
customer_behaviour
WHERE discount_applied='Yes'
GROUP BY item_purchased)
select 
item_purchased,
round(prod_pur_amt/sum(prod_pur_amt) OVER()*100,2) percentage
from CTE_product
ORDER BY percentage DESC
LIMIT 5

-- by purchase count
WITH CTE_product AS
(SELECT
item_purchased,
count(*) prod_pur_count 
FROM
customer_behaviour
WHERE discount_applied='Yes'
GROUP BY item_purchased)
select 
item_purchased,
prod_pur_count,
sum(prod_pur_count) OVER() total_sell,
round((prod_pur_count/sum(prod_pur_count) OVER())*100,2) percentage
from CTE_product
ORDER BY percentage DESC
LIMIT 5


--Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment. 
SELECT
count(*) segment_count,
	CASE 
	    WHEN previous_purchases = 1 THEN 'New'
	    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
	    ELSE 'Loyal'
	END AS customer_segment
FROM customer_behaviour
GROUP BY customer_segment
ORDER by segment_count DESC;

--Q8. What are the top 3 most purchased products within each category? 
WITH cte_cat AS
(
SELECT 
category,
item_purchased,
count(item_purchased) item_cnt,
ROW_NUMBER() OVER (PARTITION BY category ORDER BY count(item_purchased) DESC) row_num
from customer_behaviour
GROUP BY category, item_purchased
ORDER by category
)
SELECT
*
FROM cte_cat
WHERE row_num<4

 
--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status,
       COUNT(customer_id) AS repeat_buyers
FROM customer_behaviour
WHERE previous_purchases > 5
GROUP BY subscription_status;
--Q10. What is the revenue contribution of each age group? 
SELECT age_group,
       COUNT(purchase_amount_usd) AS tot_purchase_amount_usd,
	   sum(COUNT(purchase_amount_usd)) over () total_amt,
	   round(COUNT(purchase_amount_usd)/(sum(COUNT(purchase_amount_usd)) over ())*100,2) percent_contri
FROM customer_behaviour
GROUP BY age_group